<div class="section-heading studio-section-heading"><div><span class="website-kicker"><?= e($definition['group']) ?></span><h2><?= e($definition['label']) ?></h2><p class="muted">Create and organise records for this website’s local workspace.</p></div><a class="btn" href="<?= $studioPath ?>?section=<?= e($section) ?>#studio-editor">+ Add record</a></div>
<section class="card"><form class="studio-filter" method="get" action="<?= $studioPath ?>"><input type="hidden" name="section" value="<?= e($section) ?>"><label>Search<input type="search" name="q" value="<?= e($listing['query']) ?>" maxlength="150" placeholder="Search titles and details"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($definition['statuses'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $listing['status']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="secondary">Filter</button><?php if($listing['query']!=='' || $listing['status']!==''): ?><a href="<?= $studioPath ?>?section=<?= e($section) ?>">Clear</a><?php endif; ?></form><div class="section-heading"><p class="footnote"><?= $listing['count'] ?> matching <?= $listing['count']===1?'record':'records' ?></p><span class="badge">Saved on this laptop</span></div>
<?php if(!$listing['rows']): ?><div class="studio-empty"><span class="studio-empty-icon"><?= icon('folder') ?></span><h3><?= $listing['query']!=='' || $listing['status']!==''?'No matching records.':'Make room for your first record.' ?></h3><p class="muted"><?= $listing['query']!=='' || $listing['status']!==''?'Try another search or status filter.':'Use the form below. Each website keeps its own records.' ?></p></div><?php else: ?><div class="studio-record-list"><?php foreach($listing['rows'] as $record): ?><article class="studio-record-row"><div><a class="studio-record-title" href="<?= $studioPath ?>?section=<?= e($section) ?>&amp;edit=<?= e($record['id']) ?>#studio-editor"><?= e($record['title']) ?></a><div class="studio-record-meta"><span class="badge" data-status="<?= e($record['status']) ?>"><?= e($definition['statuses'][$record['status']]) ?></span><small>Updated <?= e($record['updated_at']) ?></small></div><?php $shown=0; foreach($definition['fields'] as $fieldName=>$field): if(($record['values'][$fieldName] ?? '')==='')continue; if($shown++>=2)break; ?><p class="studio-record-excerpt"><span><?= e($field['label']) ?>:</span> <?= e(mb_strimwidth($record['values'][$fieldName],0,160,'…')) ?></p><?php endforeach; ?></div><div class="studio-record-actions"><a class="btn secondary" href="<?= $studioPath ?>?section=<?= e($section) ?>&amp;edit=<?= e($record['id']) ?>#studio-editor">Edit</a><form method="post" action="<?= $studioPath ?>/records/<?= e($record['id']) ?>/trash" data-confirm="Move this local record to Trash? You can restore it later."><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($record['version']) ?>"><button class="quiet">Move to trash</button></form></div></article><?php endforeach; ?></div><?php endif; ?>
<?php if($listing['pages']>1): ?><nav class="studio-pagination" aria-label="Record pages"><?php if($listing['page']>1): ?><a href="<?= $studioPath ?>?<?= e($queryString(['section'=>$section,'q'=>$listing['query'],'status'=>$listing['status'],'page'=>$listing['page']-1])) ?>">← Previous</a><?php endif; ?><span>Page <?= $listing['page'] ?> of <?= $listing['pages'] ?></span><?php if($listing['page']<$listing['pages']): ?><a href="<?= $studioPath ?>?<?= e($queryString(['section'=>$section,'q'=>$listing['query'],'status'=>$listing['status'],'page'=>$listing['page']+1])) ?>">Next →</a><?php endif; ?></nav><?php endif; ?></section>
<section class="card studio-editor" id="studio-editor"><div class="section-heading"><div><span class="website-kicker"><?= $edit?'EDIT RECORD':'CREATE SOMETHING NEW' ?></span><h2><?= $edit?'Edit '.e($edit['title']):'Add to '.e($definition['label']) ?></h2></div><?php if($edit): ?><a href="<?= $studioPath ?>?section=<?= e($section) ?>#studio-editor">Cancel edit</a><?php endif; ?></div><form class="form-grid" method="post" action="<?= $studioPath ?>/records/<?= e($section) ?>"><?= csrf_field() ?><?php if($edit): ?><input type="hidden" name="record_id" value="<?= e($edit['id']) ?>"><input type="hidden" name="version" value="<?= e($edit['version']) ?>"><?php endif; ?><label>Title / name<input name="title" maxlength="200" value="<?= e($edit['title'] ?? '') ?>" required></label><label>Status<select name="status"><?php foreach($definition['statuses'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($edit['status'] ?? array_key_first($definition['statuses']))===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
<?php foreach($definition['fields'] as $name=>$field): $value=$edit['values'][$name] ?? ''; ?><label class="<?= $field['type']==='textarea'?'full':'' ?>"><?= e($field['label']) ?><?= $field['required']?' *':'' ?><?php if($field['type']==='textarea'): ?><textarea name="fields[<?= e($name) ?>]" rows="<?= $field['max']>10000?8:3 ?>" maxlength="<?= $field['max'] ?>" <?= $field['required']?'required':'' ?>><?= e($value) ?></textarea><?php else: ?><input name="fields[<?= e($name) ?>]" value="<?= e($value) ?>" type="<?= e(match($field['type']){'money','integer'=>'number','date'=>'date','url'=>'url','email'=>'email',default=>'text'}) ?>" maxlength="<?= $field['max'] ?>" <?= $field['type']==='money'?'min="0" step="0.01"':($field['type']==='integer'?'min="0" max="999999" step="1"':'') ?> <?= $field['type']==='color'?'placeholder="#2563eb" pattern="#[a-fA-F0-9]{6}"':'' ?> <?= $field['required']?'required':'' ?>><?php endif; ?></label><?php endforeach; ?><div class="full studio-form-footer"><button><?= $edit?'Save changes':'Create record' ?></button><span class="footnote">Saved locally. This action does not publish to the website.</span></div></form></section>
